/** Perbandingan waktu-konstan untuk hex digest. */
function vaSafeEqual(a, b) {
  var x = String(a || ''), y = String(b || '');
  if (x.length !== y.length) return false;
  var diff = 0;
  for (var i = 0; i < x.length; i++) diff |= (x.charCodeAt(i) ^ y.charCodeAt(i));
  return diff === 0;
}

