function vaLoginFail(state, username, nowSec, settings) {
  var rec = state[username];
  if (!rec || !rec.first || (nowSec - rec.first) > settings.loginWindowSec) {
    rec = { first: nowSec, fails: 0, until: 0 };
  }
  rec.fails += 1;
  if (rec.fails >= settings.loginMaxFail) {
